from typing import Dict, Any, Optional

class DotDict:
    """A dict that supports attribute-style access for keys that are valid identifiers.

    Examples:
        >>> d = DotDict(a=1, b={'c': 2})
        >>> d.a
        1
        >>> d.b.c
        2
    """
    def __init__(self, **kwargs: Any):
        for k, v in kwargs.items():
            if isinstance(v, dict):
                v = DotDict(**v)
            self.__dict__[k] = v

    def __getattr__(self, key: str) -> Any:
        if key in self.__dict__:
            return self.__dict__[key]
        raise AttributeError(key)

    def __getitem__(self, key: str) -> Any:
        return self.__dict__[key]

    def to_dict(self) -> Dict[str, Any]:
        out: Dict[str, Any] = {}
        for k, v in self.__dict__.items():
            out[k] = v.to_dict() if isinstance(v, DotDict) else v
        return out

if __name__ == "__main__":
    cfg = DotDict(name="test", nested={"value": 42, "flag": True})
    print(cfg.name, cfg.nested.value)
